	'No se ha podido enviar el email a quien la pidió: díselo tú.' => 'Non se puido enviar o email a quen a pediu: díllelo ti.',
	'Ojo: ya hay %d unidad en el inventario. ¿Seguro que hace falta comprar más?' => 'Ollo: no inventario xa hai %d unidade. Seguro que fai falta comprar máis?',
	'Ojo: ya hay %d unidades en el inventario. ¿Seguro que hace falta comprar más?' => 'Ollo: no inventario xa hai %d unidades. Seguro que fai falta comprar máis?',
	'Precio estimado, línea %d (opcional)' => 'Prezo estimado, liña %d (opcional)',
	'Quien la pidió no tiene email en el área privada: díselo tú.' => 'Quen a pediu non ten email na área privada: díllelo ti.',
	'Qué hay que comprar' => 'Que hai que comprar',
	'Se ha avisado por email a quien la pidió.' => 'Avisouse por email a quen a pediu.',
	'Se ha dado de alta %d material nuevo.' => 'Deuse de alta %d material novo.',
	'Se ha sumado lo comprado a %d material del inventario.' => 'Sumouse o comprado a %d material do inventario.',
	'Se ha sumado lo comprado a %d materiales del inventario.' => 'Sumouse o comprado a %d materiais do inventario.',
	'Se han dado de alta %d materiales nuevos.' => 'Déronse de alta %d materiais novos.',
	'Se preparan marcando el material en el inventario (y escribiendo el que todavía no está). Tesorería recibe un email y le da el visto bueno; solo entonces se puede descargar el PDF para imprimirla. Quien la pidió recibe un email con la respuesta. Cuando el material esté comprado, se marca la lista como comprada y lo comprado se suma al inventario.' => 'Prepáranse marcando o material no inventario (e escribindo o que aínda non está). Tesouraría recibe un email e dálle o visto e prace; só entón se pode descargar o PDF para imprimila. Quen a pediu recibe un email coa resposta. Cando o material estea comprado, márcase a lista como comprada e o comprado súmase ao inventario.',
	'Si hay que comprar algo que todavía no está en el inventario, escríbelo aquí. Cuando la lista se marque como comprada, se dará de alta en el inventario.' => 'Se hai que comprar algo que aínda non está no inventario, escríbeo aquí. Cando a lista se marque como comprada, darase de alta no inventario.',
	'Sin nº de serie, una fila con la misma descripción y el mismo tipo que un material que ya está en el inventario (o que otra fila del fichero) suma su cantidad a ese material en vez de crear otro. Las camisas del uniforme, solo si coinciden también el modelo y la talla.' => 'Sen nº de serie, unha fila coa mesma descrición e o mesmo tipo ca un material que xa está no inventario (ou ca outra fila do ficheiro) suma a súa cantidade a ese material en vez de crear outro. As camisas do uniforme, só se coinciden tamén o modelo e a talla.',
	'Total estimado:' => 'Total estimado:',
	'Unidades a comprar, línea %d' => 'Unidades que hai que comprar, liña %d',
	'Ya hay un material con esta descripción y este tipo, y sumándole esta cantidad pasaría de %d unidades.' => 'Xa hai un material con esta descrición e este tipo, e sumándolle esta cantidade pasaría de %d unidades.',
	'[%1$s] Tesorería ha rechazado tu lista de compra %2$s' => '[%1$s] Tesouraría rexeitou a túa lista da compra %2$s',
	'[%1$s] Tu lista de compra %2$s tiene el visto bueno de Tesorería' => '[%1$s] A túa lista da compra %2$s ten o visto e prace de Tesouraría',
	'fila sumada a un material que ya estaba (misma descripción y tipo)' => 'fila sumada a un material que xa estaba (mesma descrición e tipo)',
	'filas sumadas a un material que ya estaba (misma descripción y tipo)' => 'filas sumadas a un material que xa estaba (mesma descrición e tipo)',
	'opcional' => 'opcional',
	'¿Marcar la lista %s como comprada? Las cantidades se sumarán al inventario y el material nuevo se dará de alta. No se puede deshacer.' => 'Marcar a lista %s como comprada? As cantidades sumaranse ao inventario e o material novo darase de alta. Non se pode desfacer.',
	'¿Ya se ha comprado?' => 'Xa se comprou?',
