	'La cuenta de su ficha del CRM no es la autorizada (o no está): tiene que firmar la autorización de nuevo' => 'A conta da súa ficha do CRM non é a autorizada (ou non está): ten que asinar a autorización de novo',
	'La cuenta se guarda en la ficha del CRM y el usuario del CRM de tu grupo no tiene permiso para editar fichas. Avisa a la Tesorería del grupo.' => 'A conta gárdase na ficha do CRM e o usuario do CRM do teu grupo non ten permiso para editar fichas. Avisa á Tesouraría do grupo.',
	'La ficha del CRM solo admite cuentas de hasta %d caracteres (las españolas tienen 24): usa una cuenta española.' => 'A ficha do CRM só admite contas de ata %d caracteres (as españolas teñen 24): usa unha conta española.',
