	'Vigente · %1$s · firmada el %2$s' => 'Vixente · %1$s · asinada o %2$s',
	'⚠️ La cuenta de esta ficha no es la autorizada: no se cobrará hasta que se firme una autorización nueva.' => '⚠️ A conta desta ficha non é a autorizada: non se cobrará ata que se asine unha autorización nova.',
	'Cuenta española (24 caracteres). Se guarda, con el titular y la entidad, en la ficha de cada miembro de la familia en el CRM de Scouts de España; la web solo guarda tu autorización.' => 'Conta española (24 caracteres). Gárdase, co titular e a entidade, na ficha de cada membro da familia no CRM de Scouts de España; a web só garda a túa autorización.',
	'Entidad (banco, opcional)' => 'Entidade (banco, opcional)',
	'Los datos de la cuenta se guardan en la ficha de cada miembro de la familia en el CRM de Scouts de España; aquí solo se enseña enmascarada.' => 'Os datos da conta gárdanse na ficha de cada membro da familia no CRM de Scouts de España; aquí a conta só se amosa agochada parcialmente.',
	'⚠️ La cuenta que figura en la ficha del CRM ya no es la que autorizaste: hasta que firmes una autorización nueva no se cobrará nada por domiciliación.' => '⚠️ A conta que figura na ficha do CRM xa non é a que autorizaches: ata que asines unha autorización nova non se cobrará nada por domiciliación.',
	'Autorizar el cobro o cambiar la cuenta en «Mis pagos»' => 'Autorizar o cobro ou cambiar a conta en «Os meus pagos»',
	'Cuentas pasadas a las fichas del CRM: %1$d. Autorizaciones anuladas de las que se ha borrado la cuenta: %2$d.' => 'Contas pasadas ás fichas do CRM: %1$d. Autorizacións anuladas das que se borrou a conta: %2$d.',
	'Ver las domiciliaciones (Tesorería)' => 'Ver as domiciliacións (Tesouraría)',
	'Hay autorizaciones firmadas antes de la versión 0.33 que guardan la cuenta en la web. Pásalas a las fichas del CRM: desde entonces la web ya no guarda ninguna cuenta.' => 'Hai autorizacións asinadas antes da versión 0.33 que gardan a conta na web. Pásaas ás fichas do CRM: desde entón a web xa non garda ningunha conta.',
	'La cuenta (IBAN, titular y entidad) se guarda en la ficha del CRM de Scouts de España de cada miembro de la familia; la web guarda la autorización (quién la firmó y cuándo, y la dirección), el IBAN enmascarado y una huella para comprobar, antes de cobrar, que la cuenta del CRM sigue siendo la autorizada. La autorización se conserva mientras esté vigente y 14 meses después de anularla, como pide la norma SEPA.' => 'A conta (IBAN, titular e entidade) gárdase na ficha do CRM de Scouts de España de cada membro da familia; a web garda a autorización (quen a asinou e cando, e o enderezo), o IBAN agochado parcialmente e unha pegada para comprobar, antes de cobrar, que a conta do CRM segue sendo a autorizada. A autorización consérvase mentres estea vixente e 14 meses despois de anulala, como pide a norma SEPA.',
	'Pasar las cuentas al CRM' => 'Pasar as contas ao CRM',
	'Titular: %s' => 'Titular: %s',
	'¿Pasar las cuentas de las autorizaciones a las fichas del CRM? Se escriben en la ficha de cada miembro de la familia y se borran de la web.' => 'Queres pasar as contas das autorizacións ás fichas do CRM? Escríbense na ficha de cada membro da familia e bórranse da web.',
	'⚠️ La cuenta de su ficha del CRM no es la autorizada (o no está): no se le cobrará hasta que firme de nuevo.' => '⚠️ A conta da súa ficha do CRM non é a autorizada (ou non está): non se lle cobrará ata que asine de novo.',

