	'«Por persona: participantes y equipo» es lo que cuesta cada persona (albergue, comida): lo del equipo se reparte entre los participantes. «Solo el equipo» es lo que cuesta un scouter (p. ej. su plaza en un evento externo).' => '«Por persoa: participantes e equipo» é o que custa cada persoa (albergue, comida): o do equipo repártese entre os participantes. «Só o equipo» é o que custa un scouter (p. ex. a súa praza nun evento externo).',
