	// v0.35.1: familias, eliminar de la web
	'Eliminar de la web' => 'Eliminar da web',
	'No tiene membresía activa: deja de salir en Personas, sale de su familia y sus cuentas de acceso se desactivan. En el CRM no cambia nada; si vuelve a tener una membresía activa, vuelve a salir.' => 'Non ten membresía activa: deixa de saír en Persoas, sae da súa familia e as súas contas de acceso desactívanse. No CRM non cambia nada; se volve ter unha membresía activa, volve saír.',
	'¿Eliminar a %s de la web? Deja de salir en Personas, sale de su familia y sus cuentas de acceso se desactivan. En el CRM no cambia nada.' => 'Eliminar a %s da web? Deixa de saír en Persoas, sae da súa familia e as súas contas de acceso desactívanse. No CRM non cambia nada.',
	'No hay ningún grupo elegido.' => 'Non hai ningún grupo escollido.',
	'Solo se puede eliminar de la web a quien no tiene ninguna membresía activa. Antes, dale de baja.' => 'Só se pode eliminar da web a quen non ten ningunha membresía activa. Antes, dálle de baixa.',
