	// v0.36.1: reabrir las cuentas
	'Al cerrar, el balance de hoy queda como informe final, se borran los datos de recogida y las observaciones de las inscripciones y el evento queda en solo lectura. Si después hace falta cambiar algo, Tesorería puede reabrirlas (lo borrado no vuelve).' => 'Ao pechar, o balance de hoxe queda como informe final, bórranse os datos de recollida e as observacións das inscricións e o evento queda en só lectura. Se despois cómpre cambiar algo, Tesouraría pode reabrilas (o borrado non volve).',
	'Cuentas cerradas el %1$s por %2$s: este es el informe final. Para cambiar algo, Tesorería tiene que reabrirlas.' => 'Contas pechadas o %1$s por %2$s: este é o informe final. Para cambiar algo, Tesouraría ten que reabrilas.',
	'Cuentas del evento %s reabiertas: ya se pueden cambiar. Cuando esté todo, ciérralas de nuevo.' => 'Contas do evento %s reabertas: xa se poden cambiar. Cando estea todo, pécheas de novo.',
