	'Cambiar los datos del grupo (nombre, CIF, dirección y provincia)' => 'Cambiar os datos do grupo (nome, CIF, enderezo e provincia)',
	'El CIF tiene que tener 9 caracteres (letras y números), p. ej. G07123456.' => 'O CIF ten que ter 9 caracteres (letras e números), p. ex. G07123456.',
	'El código postal tiene que tener 5 cifras.' => 'O código postal ten que ter 5 cifras.',
