	'la provincia (sin ella no se pueden generar números de socio)' => 'a provincia (sen ela non se poden xerar números de socio)',
	'Datos del grupo' => 'Datos do grupo',
	'Falta la provincia del grupo (Datos del grupo): sin ella no se pueden generar números de socio.' => 'Falta a provincia do grupo (Datos do grupo): sen ela non se poden xerar números de socio.',
	'CIF' => 'CIF',
	'Denominación fiscal' => 'Denominación fiscal',
	'Email de contacto' => 'Email de contacto',
	'Es la unión de tres partes: los dos dígitos de la provincia (con su 0 inicial si lo lleva), el nº de grupo y un número incremental de 4 cifras.' => 'É a unión de tres partes: os dous díxitos da provincia (co seu 0 inicial se o leva), o nº de grupo e un número incremental de 4 cifras.',
	'Este grupo aún no tiene provincia: sin ella no se pueden reconocer ni generar números de socio/a.' => 'Este grupo aínda non ten provincia: sen ela non se poden recoñecer nin xerar números de socio/a.',
	'Falta por rellenar: %s.' => 'Falta por cubrir: %s.',
	'G07123456' => 'G07123456',
	'Guardar los datos del grupo' => 'Gardar os datos do grupo',
	'Lo fija quien administra la web.' => 'Fíxao quen administra a web.',
	'Los datos del grupo se escriben una sola vez, aquí: se usan en las domiciliaciones, en los documentos del grupo y para formar el nº de socio/a. Los ve todo el mundo; los cambia el equipo de Coordinación.' => 'Os datos do grupo escríbense unha soa vez, aquí: úsanse nas domiciliacións, nos documentos do grupo e para formar o nº de socio/a. Véos todo o mundo; cámbiaos o equipo de Coordinación.',
	'Los números que ya existían sin el 0 inicial (p. ej. 76840390) siguen siendo válidos tal cual; los nuevos se generan con la provincia completa.' => 'Os números que xa existían sen o 0 inicial (p. ex. 76840390) seguen sendo válidos tal cal; os novos xéranse coa provincia completa.',
	'Nº de socio/a del grupo' => 'Nº de socio/a do grupo',
	'Provincia %1$s · grupo %2$s · incremental 0001 → %3$s' => 'Provincia %1$s · grupo %2$s · incremental 0001 → %3$s',
	'Si cambio la provincia, entiendo que los números de socio/a del CRM con la provincia anterior dejarán de reconocerse como del grupo (habrá que corregirlos en el CRM). Los usuarios ya creados siguen entrando con su usuario de siempre o con su email.' => 'Se cambio a provincia, entendo que os números de socio/a do CRM coa provincia anterior deixarán de recoñecerse como do grupo (haberá que corrixilos no CRM). Os usuarios xa creados seguen entrando co seu usuario de sempre ou co seu email.',
	'— Elige la provincia —' => '— Escolle a provincia —',
	'Datos del grupo guardados.' => 'Datos do grupo gardados.',
	'No se ha encontrado el grupo.' => 'Non se atopou o grupo.',
	'No se ha guardado: para cambiar la provincia marca la casilla de confirmación (los números de socio/a del CRM con la provincia anterior dejarán de reconocerse como del grupo).' => 'Non se gardou: para cambiar a provincia marca a caixa de confirmación (os números de socio/a do CRM coa provincia anterior deixarán de recoñecerse como do grupo).',
